import AppKit
import Foundation

/// Official Antigravity brand logo (PNG, base64). Kept byte-identical to the
/// SwiftBar plugin's `ANTIGRAVITY_LOGO_B64` so both menu bars use the same mark.
enum AntigravityLogo {
    static let base64 = ""

    static let image: NSImage? = {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return NSImage(data: data)
    }()
}
